			if (item.invocation === "after-attach") return "computer";
			const haystack = `${item.name} ${item.description ?? ""} ${item.moduleName ?? ""}`.toLocaleLowerCase();
			if (/(?:pdf|document|file|research|paper|citation|spreadsheet|presentation|latex|markdown|office)/u.test(haystack)) return "research";
			if (/(?:code|git|shell|terminal|python|javascript|typescript|data|sql|test|debug|build)/u.test(haystack)) return "code";
			if (/(?:browser|web|computer|macos|screenshot|appshot|ocr|accessibility)/u.test(haystack)) return "computer";
			if (/(?:goal|plan|todo|workflow|job|task|subagent|compact)/u.test(haystack)) return "workflow";
